#!/usr/bin/env bash
# Builds the game and its test variants.
#   build/galactic-anarchy.prg   the game
#   build/test/*.prg             test builds (see test/run.sh)
# The dev build is copied to bin/, with bin/run.sh to play it.
set -euo pipefail
root="$(cd "$(dirname "$0")" && pwd)"
cd "$root"

if command -v ca65 >/dev/null && command -v ld65 >/dev/null; then
  CA65=ca65; LD65=ld65
else
  "$root/tools/toolchain.sh"
  CA65="$root/.toolchain/cc65/bin/ca65"; LD65="$root/.toolchain/cc65/bin/ld65"
fi

rm -rf build
mkdir -p build/test build/gen

# Tables, font and models, generated by our own tool (.NET 10).
nice -n 10 dotnet build tools/GaTool -c Release -o build/gatool -v q --nologo >build/gatool.log 2>&1 \
  || { cat build/gatool.log >&2; exit 1; }
build/gatool/GaTool gen build/gen models music

# assemble OUT.prg [ca65 -D options...]
assemble() {
  local out="$1"; shift
  local obj="${out%.prg}.o"
  "$CA65" --cpu 6502 -I src -I build/gen -g "$@" -o "$obj" src/main.s
  "$LD65" -C cfg/game.cfg -o "$out" -m "${out%.prg}.map" -Ln "${out%.prg}.labels" "$obj"
}

assemble build/galactic-anarchy.prg
assemble build/test/irq.prg -D TEST_IRQ=1
assemble build/test/irq-control.prg -D TEST_IRQ=1 -D NO_IRQ=1
assemble build/test/mul.prg -D TEST_MUL=1
assemble build/test/mul-control.prg -D TEST_MUL=1 -D BREAK_MUL=1
assemble build/test/play.prg -D TEST_PLAY=1
assemble build/test/play-control.prg -D TEST_PLAY=1 -D TEST_AIM_OFF=60
assemble build/test/disk-save.prg -D TEST_DISK=1
assemble build/test/disk-load.prg -D TEST_DISK=2
assemble build/test/table.prg -D TEST_DISK=3
assemble build/test/events.prg -D TEST_PLAY=1 -D TEST_EVENTS=1 -D TEST_AIM_OFF=60
assemble build/test/events-control.prg -D TEST_PLAY=1 -D TEST_EVENTS=1 -D TEST_AIM_OFF=60 -D NO_RIVALS=1
assemble build/test/ring.prg -D TEST_PLAY=1 -D TEST_MISSION=2
assemble build/test/ring-control.prg -D TEST_PLAY=1 -D TEST_MISSION=2 -D TEST_AIM_CORNER=1
assemble build/test/convoy.prg -D TEST_PLAY=1 -D TEST_MISSION=1
assemble build/test/convoy-control.prg -D TEST_PLAY=1 -D TEST_MISSION=1 -D TEST_AIM_CORNER=1
assemble build/test/boss.prg -D TEST_PLAY=1 -D TEST_BOSS=1
assemble build/test/boss-control.prg -D TEST_PLAY=1 -D TEST_BOSS=1 -D TEST_AIM_OFF=60
for scene in 1 2 3 5; do
  assemble "build/test/bench-$scene.prg" -D BENCH=$scene
done
# One roster build per enemy (scene 4 showing item n).
roster_count=$(sed -n 's/^ROSTER_COUNT = //p' build/gen/models.inc)
for ((n = 0; n < roster_count; n++)); do
  assemble "build/test/roster-$n.prg" -D BENCH=4 -D ROSTER_ITEM=$n
done

# The disk: the game and the first high-score file (its load address is the table's).
table=$(sed -n 's/^al 00\([0-9A-F]*\) \.hs_table$/\1/p' build/galactic-anarchy.labels)
build/gatool/GaTool scores build/ga-scores.prg "$table"
build/gatool/GaTool d64 build/galactic-anarchy.d64 "GALACTIC ANARCHY" GA \
  "GALACTIC ANARCHY=build/galactic-anarchy.prg" "GA SCORES=build/ga-scores.prg"

mkdir -p bin
cp build/galactic-anarchy.d64 bin/
cp build/galactic-anarchy.prg bin/
cp tools/run.sh bin/run.sh
chmod +x bin/run.sh
echo "built build/galactic-anarchy.prg ($(stat -c %s build/galactic-anarchy.prg) bytes)"
